using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;

#if UNITY_EDITOR
using UnityEditor;
#endif

namespace Arosoul.Transitions
{
    /// <summary>
    /// Runtime lookup of all transition definitions in the project.
    /// Generated by the editor and included in builds as a preloaded asset. Do not edit manually.
    /// </summary>
    public class TransitionRegistry : ScriptableObject
    {
        [SerializeField] private List<TransitionDefinition> _definitions = new();

        [SerializeField, Tooltip("Optional. If empty a default panel settings object is created at runtime.")]
        private PanelSettings _panelSettings;

        [SerializeField, Tooltip("Sorting order of the overlay panel. Should be above all other UI.")]
        private float _sortingOrder = 32000f;

        [NonSerialized] private Dictionary<int, TransitionDefinition> _byId;

        public IReadOnlyList<TransitionDefinition> Definitions => _definitions;
        public PanelSettings PanelSettings => _panelSettings;
        public float SortingOrder => _sortingOrder;

        private static TransitionRegistry _instance;

        public static TransitionRegistry Instance
        {
            get
            {
                if (_instance == null)
                    _instance = Find();
                return _instance;
            }
        }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics()
        {
            _instance = null;
        }

        private static TransitionRegistry Find()
        {
#if UNITY_EDITOR
            string[] guids = AssetDatabase.FindAssets($"t:{nameof(TransitionRegistry)}");
            for (int i = 0; i < guids.Length; i++)
            {
                var registry = AssetDatabase.LoadAssetAtPath<TransitionRegistry>(AssetDatabase.GUIDToAssetPath(guids[i]));
                if (registry != null) return registry;
            }
            return null;
#else
            var registries = Resources.FindObjectsOfTypeAll<TransitionRegistry>();
            return registries.Length > 0 ? registries[0] : null;
#endif
        }

        private void OnEnable()
        {
            _byId = null;
        }

        public bool TryGet(TransitionId id, out TransitionDefinition definition)
        {
            if (_byId == null)
            {
                _byId = new Dictionary<int, TransitionDefinition>();
                for (int i = 0; i < _definitions.Count; i++)
                {
                    var def = _definitions[i];
                    if (def == null || def.Id.IsNone) continue;
                    _byId[def.Id.Value] = def;
                }
            }
            return _byId.TryGetValue(id.Value, out definition);
        }

        public static bool TryGetDefinition(TransitionId id, out TransitionDefinition definition)
        {
            definition = null;
            var registry = Instance;
            return registry != null && registry.TryGet(id, out definition);
        }

        public static bool TryGetKey(TransitionId id, out string key)
        {
            key = null;
            if (!TryGetDefinition(id, out TransitionDefinition definition)) return false;
            key = definition.Key;
            return true;
        }

        internal void SetDefinitions(IEnumerable<TransitionDefinition> definitions)
        {
            _definitions = new List<TransitionDefinition>(definitions);
            _byId = null;
        }

        internal static void SetInstanceForTests(TransitionRegistry registry)
        {
            _instance = registry;
        }
    }
}
